    public async Task<ActionResult<PostDto>> Create(Guid blogId, [FromBody] PostInput input, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(input.Title)) return BadRequest();
        if (!await db.Blogs.AnyAsync(b => b.Id == blogId, ct)) return NotFound();
        var post = new Post { Id = Guid.NewGuid(), BlogId = blogId, Title = input.Title, Views = 0 };
        db.Posts.Add(post);
        await db.SaveChangesAsync(ct);
        return CreatedAtAction(nameof(Get), new { id = post.Id }, new PostDto(post.Id, post.BlogId, post.Title));
    }

    [HttpGet("api/posts/{id:guid}")]
    public async Task<ActionResult<PostDto>> Get(Guid id, CancellationToken ct)
    {
        var post = await db.Posts.FirstOrDefaultAsync(p => p.Id == id, ct);
        if (post is null) return NotFound();
        post.Views++;
        await db.SaveChangesAsync(ct);
        return new PostDto(post.Id, post.BlogId, post.Title);
