Notes:
- `GET /api/posts/{id}` increments `Views` on each read, since the spec says the server maintains the counter and doesn't say what triggers it. Tell me if you want a different trigger.
- Deleting a blog cascades to its posts through the foreign key.
- Responses use `BlogDto` and `PostDto`, so `Views` and the navigation collection are never serialized.
- Missing or blank names and titles return 400, and unknown ids return 404.

```csharp
using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

public class Blog
{
    public Guid Id { get; set; }
    public string Name { get; set; } = "";
    public int Version { get; set; }
    public List<Post> Posts { get; set; } = new();
}

public class Post
{
    public Guid Id { get; set; }
    public Guid BlogId { get; set; }
    public Blog Blog { get; set; } = null!;
    public string Title { get; set; } = "";
    public int Views { get; set; }
    public int Version { get; set; }
}

public record BlogDto(Guid Id, string Name);
public record PostDto(Guid Id, Guid BlogId, string Title);

public class BlogInput
{
    public Guid? Id { get; set; }
    [Required] public string Name { get; set; } = "";
}

public class PostInput
{
    public Guid? Id { get; set; }
    [Required] public string Title { get; set; } = "";
}

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(b =>
        {
            b.HasKey(x => x.Id);
            b.Property(x => x.Name).IsRequired();
            b.Property(x => x.Version).IsConcurrencyToken();
            b.HasMany(x => x.Posts).WithOne(p => p.Blog).HasForeignKey(p => p.BlogId).OnDelete(DeleteBehavior.Cascade);
        });

        modelBuilder.Entity<Post>(p =>
        {
            p.HasKey(x => x.Id);
            p.Property(x => x.Title).IsRequired();
            p.Property(x => x.Views).HasDefaultValue(0);
            p.Property(x => x.Version).IsConcurrencyToken();
        });
    }
}

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString)
    {
        services.AddDbContext<AppDbContext>(o => o.UseSqlite(sqliteConnectionString));
        services.AddControllers();
    }
}

[ApiController]
[Route("api/blogs")]
public class BlogsController(AppDbContext db) : ControllerBase
{
    [HttpPost]
    public async Task<IActionResult> Create(BlogInput input, CancellationToken ct)
    {
        var id = input.Id ?? Guid.NewGuid();
        var existing = await db.Blogs.AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct);
        if (existing is not null)
            return existing.Name == input.Name ? Ok(ToDto(existing)) : Conflict();

        var blog = new Blog { Id = id, Name = input.Name };
        db.Blogs.Add(blog);
        await db.SaveChangesAsync(ct);
        return CreatedAtAction(nameof(Get), new { id }, ToDto(blog));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await db.Blogs.AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct);
        return blog is null ? NotFound() : Ok(ToDto(blog));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, BlogInput input, CancellationToken ct)
    {
        var blog = await db.Blogs.FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null) return NotFound();

        blog.Name = input.Name;
        blog.Version++;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }
        return Ok(ToDto(blog));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var deleted = await db.Blogs.Where(b => b.Id == id).ExecuteDeleteAsync(ct);
        return deleted == 0 ? NotFound() : NoContent();
    }

    private static BlogDto ToDto(Blog b) => new(b.Id, b.Name);
}

[ApiController]
public class PostsController(AppDbContext db) : ControllerBase
{
    [HttpPost("api/blogs/{blogId:guid}/posts")]
    public async Task<IActionResult> Create(Guid blogId, PostInput input, CancellationToken ct)
    {
        if (!await db.Blogs.AnyAsync(b => b.Id == blogId, ct)) return NotFound();

        var id = input.Id ?? Guid.NewGuid();
        var existing = await db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == id, ct);
        if (existing is not null)
            return existing.BlogId == blogId && existing.Title == input.Title ? Ok(ToDto(existing)) : Conflict();

        var post = new Post { Id = id, BlogId = blogId, Title = input.Title };
        db.Posts.Add(post);
        await db.SaveChangesAsync(ct);
        return CreatedAtAction(nameof(Get), new { id }, ToDto(post));
    }

    [HttpGet("api/posts/{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var viewed = await db.Posts.Where(p => p.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1), ct);
        if (viewed == 0) return NotFound();

        var post = await db.Posts.AsNoTracking().FirstAsync(p => p.Id == id, ct);
        return Ok(ToDto(post));
    }

    [HttpPut("api/posts/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, PostInput input, CancellationToken ct)
    {
        var post = await db.Posts.FirstOrDefaultAsync(p => p.Id == id, ct);
        if (post is null) return NotFound();

        post.Title = input.Title;
        post.Version++;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }
        return Ok(ToDto(post));
    }

    [HttpDelete("api/posts/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var deleted = await db.Posts.Where(p => p.Id == id).ExecuteDeleteAsync(ct);
        return deleted == 0 ? NotFound() : NoContent();
    }

    private static PostDto ToDto(Post p) => new(p.Id, p.BlogId, p.Title);
}
```

Design notes:
- **Retries:** `POST` accepts an optional client-supplied `id`. A retry with the same id and same content returns the existing resource with 200 instead of creating a duplicate. A different payload for an existing id returns 409.
- **Concurrent edits:** `Version` is an EF concurrency token that is hidden from JSON. A stale `PUT` that loses the race gets 409 instead of silently overwriting.
- **Views:** `GET /api/posts/{id}` increments `Views` atomically in SQL with `ExecuteUpdate`, so concurrent reads don't lose counts. `Views` is not included in the post JSON, which keeps the response to the specified shape.
- **Cascade:** deleting a blog deletes its posts through the database `ON DELETE CASCADE` foreign key.
- **Not covered:** `blogId` is immutable on post update, and a repeated `DELETE` returns 404. Two simultaneous creates with the same client id can still surface as a 500 from the unique-key violation.

