```csharp
using System.Security.Cryptography;
using System.Text;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;

public class Blog
{
    public int Key { get; set; }
    public Guid Id { get; set; }
    public string Name { get; set; } = "";
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTime? Tombstone { get; set; }
}

public class Post
{
    public int Key { get; set; }
    public Guid Id { get; set; }
    public Guid BlogId { get; set; }
    public string Title { get; set; } = "";
    public int Views { get; set; }
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTime? Tombstone { get; set; }
}

public static class Canonical
{
    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    public static string BlogTag(Guid id, string name) =>
        Tag($"{{\"id\":\"{id:D}\",\"name\":{Str(name)}}}");

    public static string PostTag(Guid id, Guid blogId, string title) =>
        Tag($"{{\"id\":\"{id:D}\",\"blogId\":\"{blogId:D}\",\"title\":{Str(title)}}}");

    static string Tag(string json) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(json)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in Nfc(s))
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                _ when c < 0x20 => $"\\u{(int)c:x4}",
                _ => c.ToString()
            });
        return sb.Append('"').ToString();
    }
}

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder mb)
    {
        mb.Entity<Blog>(b =>
        {
            b.HasKey(x => x.Key);
            b.HasIndex(x => x.Id).IsUnique();
            b.Property(x => x.Name).IsRequired();
            b.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            b.Property(x => x.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            b.HasQueryFilter(x => x.Tombstone == null);
        });

        mb.Entity<Post>(p =>
        {
            p.HasKey(x => x.Key);
            p.HasIndex(x => x.Id).IsUnique();
            p.HasIndex(x => x.BlogId);
            p.Property(x => x.Title).IsRequired();
            p.Property(x => x.ETag).IsRequired().IsConcurrencyToken();
            p.Property(x => x.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
            p.HasQueryFilter(x => x.Tombstone == null);
        });
    }
}

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString) =>
        services.AddDbContext<AppDbContext>(o => o.UseSqlite(sqliteConnectionString));
}
