```csharp
using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public class BlogRequest
{
    [Required] public Guid? Id { get; set; }
    [Required(AllowEmptyStrings = false)] public string? Name { get; set; }
}

public class PostRequest
{
    [Required] public Guid? Id { get; set; }
    [Required] public Guid? BlogId { get; set; }
    [Required(AllowEmptyStrings = false)] public string? Title { get; set; }
}

public record BlogResponse(Guid Id, string Name);
public record PostResponse(Guid Id, Guid BlogId, string Title);

public abstract class ApiControllerBase : ControllerBase
{
    protected ApiControllerBase(AppDbContext db) => Db = db;

    protected AppDbContext Db { get; }

    protected IActionResult Fail(int status) => new ObjectResult(new ProblemDetails
    {
        Status = status,
        Title = status switch
        {
            400 => "Bad Request",
            404 => "Not Found",
            409 => "Conflict",
            410 => "Gone",
            412 => "Precondition Failed",
            428 => "Precondition Required",
            _ => "Error"
        }
    }) { StatusCode = status, ContentType = "application/problem+json" };

    protected void SetETag(string etag) => Response.Headers["ETag"] = etag;

    protected static bool Matches(string header, string etag) =>
        header.Trim() == "*" || header.Split(',').Any(t => t.Trim() == etag);

    protected static bool IsUnique(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteErrorCode: 19 };

    protected async Task<bool> TrySaveAsync(CancellationToken ct)
    {
        try
        {
            await Db.SaveChangesAsync(ct);
            return true;
        }
        catch (DbUpdateConcurrencyException)
        {
            Db.ChangeTracker.Clear();
            return false;
        }
    }
}

[Route("api/blogs")]
public class BlogsController(AppDbContext db) : ApiControllerBase(db)
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] BlogRequest? body, CancellationToken ct)
    {
        if (body is null || !TryValidateModel(body)) return Fail(400);
        var id = body.Id!.Value;
        var name = Canonical.Nfc(body.Name!);
        var tag = Canonical.BlogTag(id, name);
        try
        {
            Db.Blogs.Add(new Blog { Id = id, Name = name, ETag = tag, CreateHash = tag });
            await Db.SaveChangesAsync(ct);
            SetETag(tag);
            return Created($"/api/blogs/{id:D}", new BlogResponse(id, name));
        }
        catch (DbUpdateException ex) when (IsUnique(ex))
        {
            Db.ChangeTracker.Clear();
        }

        var existing = await Db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstAsync(b => b.Id == id, ct);
        if (existing.Tombstone is not null) return Fail(410);
        if (existing.CreateHash != tag) return Fail(409);
        SetETag(existing.ETag);
        return Ok(new BlogResponse(existing.Id, existing.Name));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await Db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null) return Fail(404);
        if (blog.Tombstone is not null) return Fail(410);
        SetETag(blog.ETag);
        if (Matches(Request.Headers["If-None-Match"].ToString(), blog.ETag)) return StatusCode(304);
        return Ok(new BlogResponse(blog.Id, blog.Name));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody, Required] BlogRequest? body,
        [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (body is null || !TryValidateModel(body) || body.Id != id) return Fail(400);
        if (ifMatch is null) return Fail(428);

        var blog = await Db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null) return Fail(404);
        if (blog.Tombstone is not null) return Fail(410);

        var name = Canonical.Nfc(body.Name!);
        var tag = Canonical.BlogTag(id, name);
        if (blog.ETag == tag)
        {
            SetETag(tag);
            return NoContent();
        }
        if (!Matches(ifMatch, blog.ETag))
        {
            SetETag(blog.ETag);
            return Fail(412);
        }

        blog.Name = name;
        blog.ETag = tag;
        if (await TrySaveAsync(ct))
        {
            SetETag(tag);
            return NoContent();
        }

        var cur = await Db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct);
        if (cur is null) return Fail(404);
        if (cur.Tombstone is not null) return Fail(410);
        SetETag(cur.ETag);
        if (cur.ETag == tag) return NoContent();
        return Fail(412);
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (ifMatch is null) return Fail(428);

        var blog = await Db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null || blog.Tombstone is not null) return NoContent();
        if (!Matches(ifMatch, blog.ETag))
        {
            SetETag(blog.ETag);
            return Fail(412);
        }

        var now = DateTime.UtcNow;
        blog.Tombstone = now;
        var posts = await Db.Posts.Where(p => p.BlogId == id).ToListAsync(ct);
        foreach (var p in posts) p.Tombstone = now;

        if (await TrySaveAsync(ct)) return NoContent();

        var cur = await Db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct);
        if (cur is null || cur.Tombstone is not null) return NoContent();
        SetETag(cur.ETag);
        return Fail(412);
    }
}

[Route("api")]
public class PostsController(AppDbContext db) : ApiControllerBase(db)
{
    [HttpPost("blogs/{blogId:guid}/posts")]
    [ProducesResponseType(typeof(PostResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(PostResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(Guid blogId, [FromBody, Required] PostRequest? body, CancellationToken ct)
    {
        if (body is null || !TryValidateModel(body) || body.BlogId != blogId) return Fail(400);

        var blog = await Db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(b => b.Id == blogId, ct);
        if (blog is null) return Fail(404);
        if (blog.Tombstone is not null) return Fail(410);

        var id = body.Id!.Value;
        var title = Canonical.Nfc(body.Title!);
        var tag = Canonical.PostTag(id, blogId, title);
        try
        {
            Db.Posts.Add(new Post { Id = id, BlogId = blogId, Title = title, ETag = tag, CreateHash = tag });
            await Db.SaveChangesAsync(ct);
