        {
            Db.ChangeTracker.Clear();
        }

        var existing = await Db.Posts.IgnoreQueryFilters().AsNoTracking().FirstAsync(p => p.Id == id, ct);
        if (existing.Tombstone is not null) return Fail(410);
        if (existing.CreateHash != tag) return Fail(409);
        SetETag(existing.ETag);
        return Ok(new PostResponse(existing.Id, existing.BlogId, existing.Title));
    }

