        var post = await Db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(p => p.Id == id, ct);
        if (post is null || post.Tombstone is not null) return NoContent();
        if (!Matches(ifMatch, post.ETag))
        {
            SetETag(post.ETag);
            return Fail(412);
        }

        post.Tombstone = DateTime.UtcNow;
        if (await TrySaveAsync(ct)) return NoContent();

        var cur = await Db.Posts.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(p => p.Id == id, ct);
        if (cur is null || cur.Tombstone is not null) return NoContent();
        SetETag(cur.ETag);
        return Fail(412);
    }
}
