**ETag canonicalisation and DTOs**

```csharp
using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public sealed record TicketRequest(Guid? Id, string? Subject, int? Priority, bool? Escalated, string? Category);
public sealed record TicketValues(Guid Id, string Subject, int Priority, bool Escalated, string Category);
public sealed record TicketResponse(Guid Id, string Subject, int Priority, bool Escalated, string Category);

public static class TicketHash
{
    public static string ETag(TicketValues v)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(Canonical(v)));
        return "\"" + Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    static string Canonical(TicketValues v) =>
        $"{{\"id\":\"{v.Id:D}\",\"subject\":{Str(v.Subject)},\"priority\":{v.Priority.ToString(CultureInfo.InvariantCulture)},\"escalated\":{(v.Escalated ? "true" : "false")},\"category\":{Str(v.Category)}}}";

    static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s.Normalize(NormalizationForm.FormC))
            sb.Append(c switch
            {
                '"' => "\\\"",
                '\\' => "\\\\",
                '\b' => "\\b",
                '\f' => "\\f",
                '\n' => "\\n",
                '\r' => "\\r",
                '\t' => "\\t",
                _ when c < 0x20 => $"\\u{(int)c:x4}",
                _ => c.ToString()
            });
        return sb.Append('"').ToString();
    }
}
