using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController(SupportDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody, Required] TicketRequest? body, CancellationToken ct)
    {
        var v = Parse(body);
        if (v is null) return Fail(400, "Invalid support ticket.");
        var etag = TicketHash.ETag(v);
        var ticket = new Ticket
        {
            PublicId = v.Id, Subject = v.Subject, Priority = v.Priority, Escalated = v.Escalated,
            Category = v.Category, ETag = etag, CreateHash = etag
        };
        db.Tickets.Add(ticket);
        try
        {
            await db.SaveChangesAsync(ct);
            Response.Headers["ETag"] = etag;
            return Created($"/api/support-tickets/{v.Id:D}", Rep(ticket));
        }
        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteErrorCode: 19 })
        {
            db.ChangeTracker.Clear();
            var existing = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(x => x.PublicId == v.Id, ct);
            if (existing?.DeletedAt is not null) return Fail(410, "Gone.");
            if (existing is null || existing.CreateHash != etag) return Fail(409, "A ticket with this id already exists.");
            Response.Headers["ETag"] = existing.ETag;
            return Ok(Rep(existing));
        }
    }

    [HttpGet("{id}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var t = await db.Tickets.AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return await NotFoundOrGone(id, ct);
        Response.Headers["ETag"] = t.ETag;
        if (Matches(Request.Headers.IfNoneMatch.ToString(), t.ETag))
            return StatusCode(StatusCodes.Status304NotModified);
        await db.Tickets.Where(x => x.PublicId == id).ExecuteUpdateAsync(s => s
            .SetProperty(x => x.ViewCount, x => x.ViewCount + 1)
            .SetProperty(x => x.LastViewedAt, DateTime.UtcNow), ct);
        return Ok(Rep(t));
    }

    [HttpPut("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(
        Guid id,
        [ValidateNever, Required, FromHeader(Name = "If-Match")] string? ifMatch,
        [FromBody, Required] TicketRequest? body,
        CancellationToken ct)
    {
        var v = Parse(body);
        if (v is null || v.Id != id) return Fail(400, "Invalid support ticket or id mismatch.");
        if (ifMatch is null) return Fail(428, "If-Match header is required.");
        var etag = TicketHash.ETag(v);
        var t = await db.Tickets.FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return await NotFoundOrGone(id, ct);
        if (t.ETag == etag) return Done(etag);
        if (!Matches(ifMatch, t.ETag)) return Precondition(t.ETag);
        t.Subject = v.Subject;
        t.Priority = v.Priority;
        t.Escalated = v.Escalated;
        t.Category = v.Category;
        t.ETag = etag;
        try
        {
            await db.SaveChangesAsync(ct);
            return Done(etag);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var cur = await db.Tickets.AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is null) return await NotFoundOrGone(id, ct);
            return cur.ETag == etag ? Done(etag) : Precondition(cur.ETag);
        }
    }

    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(
        Guid id,
        [ValidateNever, Required, FromHeader(Name = "If-Match")] string? ifMatch,
        CancellationToken ct)
    {
        if (ifMatch is null) return Fail(428, "If-Match header is required.");
        var t = await db.Tickets.FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return NoContent();
        if (!Matches(ifMatch, t.ETag)) return Precondition(t.ETag);
        t.DeletedAt = DateTime.UtcNow;
        try
        {
            await db.SaveChangesAsync(ct);
            return NoContent();
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var cur = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(x => x.PublicId == id, ct);
            return cur is null || cur.DeletedAt is not null ? NoContent() : Precondition(cur.ETag);
        }
    }

    async Task<IActionResult> NotFoundOrGone(Guid id, CancellationToken ct) =>
        await db.Tickets.IgnoreQueryFilters().AnyAsync(x => x.PublicId == id && x.DeletedAt != null, ct)
            ? Fail(410, "Gone.")
            : Fail(404, "Not found.");

    IActionResult Precondition(string etag)
    {
        Response.Headers["ETag"] = etag;
        return Fail(412, "Precondition failed.");
    }

    IActionResult Done(string etag)
    {
        Response.Headers["ETag"] = etag;
        return NoContent();
    }

    static TicketValues? Parse(TicketRequest? r) =>
        r is not null && r.Id is { } id && id != Guid.Empty
        && r.Subject is { } s && s.Trim().Length > 0
        && r.Priority is { } p && r.Escalated is { } e && r.Category is { } c
            ? new TicketValues(id, s, p, e, c)
            : null;

    static bool Matches(string header, string etag) =>
        header.Split(',').Select(s => s.Trim()).Any(s => s == "*" || s == etag);

    static TicketResponse Rep(Ticket t) => new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);

    static ObjectResult Fail(int status, string title)
    {
        var r = new ObjectResult(new ProblemDetails { Status = status, Title = title }) { StatusCode = status };
        r.ContentTypes.Add("application/problem+json");
        return r;
    }
}
