using System.ComponentModel.DataAnnotations;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

namespace Inventory;

internal static class Support
{
    public const string ProblemJson = "application/problem+json";

    public static bool Matches(string header, string etag) =>
        header.Split(',').Select(v => v.Trim()).Any(v => v == "*" || v == etag);

    public static string Warehouse(Guid id, string code, int capacity) =>
        "{\"id\":" + Id(id) + ",\"code\":" + Str(code) + ",\"capacityCubicMeters\":" + capacity.ToString(CultureInfo.InvariantCulture) + "}";

    public static string Shipment(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile) =>
        "{\"id\":" + Id(id) + ",\"warehouseId\":" + Id(warehouseId) + ",\"reference\":" + Str(reference) +
        ",\"weightKg\":" + Num(weightKg) + ",\"fragile\":" + (fragile ? "true" : "false") + "}";

    public static string ETag(string canonicalJson)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson));
        return "\"" + Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    public static bool IsUniqueViolation(this DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 or 1555 };

    private static string Id(Guid g) => "\"" + g.ToString("D") + "\"";

    private static string Num(decimal d) => decimal.Normalize(d).ToString(CultureInfo.InvariantCulture);

    private static string Str(string s)
    {
        var sb = new StringBuilder().Append('"');
        foreach (var c in s.Normalize(NormalizationForm.FormC))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }
}

public abstract class ApiBase : ControllerBase
{
    protected IActionResult Fail(int status) => Problem(statusCode: status);

    protected IActionResult Precondition(string currentEtag)
    {
        Response.Headers["ETag"] = currentEtag;
        return Problem(statusCode: StatusCodes.Status412PreconditionFailed);
    }

    protected async Task<IActionResult> Stale<T>(IQueryable<T> set, Guid id, CancellationToken ct) where T : class, IResource
    {
        var current = await set.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(x => x.PublicId == id, ct);
        if (current is null) return Fail(StatusCodes.Status404NotFound);
        if (current.DeletedAt is not null) return Fail(StatusCodes.Status410Gone);
        return Precondition(current.ETag);
    }
}

[Route("api/warehouses")]
public sealed class WarehousesController(InventoryDbContext db) : ApiBase
{
    [HttpPost]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, Support.ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, Support.ProblemJson)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, Support.ProblemJson)]
    public async Task<IActionResult> Create([Required, FromBody] WarehouseRequest? body, CancellationToken ct)
    {
        if (body is null || !body.IsValid) return Fail(StatusCodes.Status400BadRequest);
        var id = body.Id!.Value;
        var code = body.Code!;
        var cap = body.CapacityCubicMeters!.Value;
        var etag = Support.ETag(Support.Warehouse(id, code, cap));
        var depot = new Depot { PublicId = id, Code = code, CapacityCubicMeters = cap, ETag = etag, CreateHash = etag, LastAuditAt = DateTime.UtcNow };
        db.Depots.Add(depot);
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (ex.IsUniqueViolation())
        {
            db.Entry(depot).State = EntityState.Detached;
            var existing = await db.Depots.IgnoreQueryFilters().AsNoTracking().SingleOrDefaultAsync(d => d.PublicId == id, ct);
            if (existing is null) throw;
            if (existing.DeletedAt is not null) return Fail(StatusCodes.Status410Gone);
            if (existing.CreateHash != etag) return Fail(StatusCodes.Status409Conflict);
            Response.Headers["ETag"] = existing.ETag;
            return Ok(new WarehouseResponse(id, existing.Code, existing.CapacityCubicMeters));
        }
        Response.Headers["ETag"] = etag;
        return Created($"/api/warehouses/{id:D}", new WarehouseResponse(id, code, cap));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, Support.ProblemJson)]
