public static class Canon
{
    public static string Nfc(string s) => s.Normalize(NormalizationForm.FormC);

    static void Str(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in Nfc(s))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    static string Hash(string json) =>
        "\"" + Base64Url.EncodeToString(SHA256.HashData(Encoding.UTF8.GetBytes(json))) + "\"";

    public static string BlogETag(Guid id, string name)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"name\":");
        Str(sb, name);
        sb.Append('}');
        return Hash(sb.ToString());
    }

    public static string PostETag(Guid id, Guid blogId, string title)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D")).Append("\",\"blogId\":\"").Append(blogId.ToString("D")).Append("\",\"title\":");
        Str(sb, title);
        sb.Append('}');
        return Hash(sb.ToString());
    }

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/", StringComparison.Ordinal)) t = t[2..];
            if (t == etag) return true;
        }
        return false;
    }
}

