[Route("api/support-tickets")]
public class SupportTicketsController : ControllerBase
{
    private readonly AppDbContext _db;
    public SupportTicketsController(AppDbContext db) => _db = db;

    private IActionResult Respond(Ticket t, bool created)
    {
        Response.Headers.ETag = $"\"{t.Version}\"";
        var body = TicketResponse.From(t);
        return created
            ? Created($"/api/support-tickets/{t.Id}", body)
            : Ok(body);
    }

    private static bool Valid(TicketRequest? r) => r != null && !string.IsNullOrWhiteSpace(r.Subject);

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] TicketRequest? req, CancellationToken ct)
    {
        if (!Valid(req)) return BadRequest(new { error = "subject is required" });

        string? key = Request.Headers["Idempotency-Key"].FirstOrDefault();
        if (string.IsNullOrWhiteSpace(key)) key = null;

        var existing = await FindExisting(key, req!.Id, ct);
        if (existing != null) return Respond(existing, false);

        var ticket = new Ticket
        {
            Id = req.Id ?? Guid.NewGuid(),
            Subject = req.Subject!,
            Priority = req.Priority ?? 0,
            Escalated = req.Escalated ?? false,
            Category = req.Category ?? "",
        };
        _db.Tickets.Add(ticket);
        if (key != null) _db.IdempotencyRecords.Add(new IdempotencyRecord { Key = key, TicketId = ticket.Id });

        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            _db.ChangeTracker.Clear();
            existing = await FindExisting(key, req.Id, ct);
            if (existing != null) return Respond(existing, false);
            throw;
        }
        return Respond(ticket, true);
    }

    private async Task<Ticket?> FindExisting(string? key, Guid? id, CancellationToken ct)
    {
        if (key != null)
        {
            var rec = await _db.IdempotencyRecords.AsNoTracking().FirstOrDefaultAsync(r => r.Key == key, ct);
            if (rec != null)
                return await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == rec.TicketId, ct);
        }
        if (id != null)
            return await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        return null;
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var rows = await _db.Tickets.Where(t => t.Id == id).ExecuteUpdateAsync(s => s
            .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
            .SetProperty(t => t.LastViewedAt, now), ct);
        if (rows == 0) return NotFound();
        var ticket = await _db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        return ticket == null ? NotFound() : Respond(ticket, false);
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] TicketRequest? req, CancellationToken ct)
    {
        if (!Valid(req)) return BadRequest(new { error = "subject is required" });
        if (req!.Id != null && req.Id != id) return BadRequest(new { error = "id mismatch" });

        int? expected = null;
        var ifMatch = Request.Headers.IfMatch.FirstOrDefault();
        if (!string.IsNullOrWhiteSpace(ifMatch) && ifMatch.Trim() != "*")
        {
            var v = ifMatch.Trim();
            if (v.StartsWith("W/")) v = v[2..];
            v = v.Trim('"');
            if (!int.TryParse(v, out var parsed)) return StatusCode(StatusCodes.Status412PreconditionFailed);
            expected = parsed;
        }

        string subject = req.Subject!;
        int priority = req.Priority ?? 0;
        bool escalated = req.Escalated ?? false;
        string category = req.Category ?? "";

        var query = _db.Tickets.Where(t => t.Id == id);
        if (expected != null) query = query.Where(t => t.Version == expected.Value);

        var rows = await query.ExecuteUpdateAsync(s => s
            .SetProperty(t => t.Subject, subject)
            .SetProperty(t => t.Priority, priority)
            .SetProperty(t => t.Escalated, escalated)
            .SetProperty(t => t.Category, category)
            .SetProperty(t => t.Version, t => t.Version + 1), ct);

        if (rows == 0)
        {
            var exists = await _db.Tickets.AnyAsync(t => t.Id == id, ct);
            return exists ? StatusCode(StatusCodes.Status412PreconditionFailed) : NotFound();
        }

        var ticket = await _db.Tickets.AsNoTracking().FirstAsync(t => t.Id == id, ct);
        return Respond(ticket, false);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var rows = await _db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync(ct);
        if (rows == 0) return NotFound();
        await _db.IdempotencyRecords.Where(r => r.TicketId == id).ExecuteDeleteAsync(ct);
        return NoContent();
    }
}
