public static class Canon
{
    static void Str(StringBuilder sb, string s)
    {
        sb.Append('"');
        foreach (var c in s.Normalize(NormalizationForm.C))
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else sb.Append(c);
                    break;
            }
        }
        sb.Append('"');
    }

    public static string Etag(Guid id, string subject, int priority, bool escalated, string category)
    {
        var sb = new StringBuilder();
        sb.Append("{\"id\":\"").Append(id.ToString("D").ToLowerInvariant()).Append("\",\"subject\":");
        Str(sb, subject);
        sb.Append(",\"priority\":").Append(priority.ToString(CultureInfo.InvariantCulture));
        sb.Append(",\"escalated\":").Append(escalated ? "true" : "false");
        sb.Append(",\"category\":");
        Str(sb, category);
        sb.Append('}');
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(sb.ToString()));
        var b64 = Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        return "\"" + b64 + "\"";
    }

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var p = raw.Trim();
            if (p == "*") return true;
            if (p.StartsWith("W/", StringComparison.Ordinal)) p = p[2..];
            if (p == etag) return true;
        }
        return false;
    }
}

