public class SupportTicketsController : ControllerBase
{
    const string ProblemType = "application/problem+json";
    readonly AppDbContext _db;

    public SupportTicketsController(AppDbContext db) => _db = db;

    IActionResult Err(int status, string title) =>
        new ObjectResult(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { ProblemType }
        };

    static TicketResponse Map(Ticket t) => new()
    {
        Id = t.PublicId,
        Subject = t.Subject,
        Priority = t.Priority,
        Escalated = t.Escalated,
        Category = t.Category
    };

    bool BodyInvalid(TicketRequest? body)
    {
        ModelState.Remove("If-Match");
        ModelState.Remove("ifMatch");
        return body == null || !ModelState.IsValid || string.IsNullOrWhiteSpace(body.Subject)
            || body.Category == null || body.Priority == null || body.Escalated == null;
    }

    static string Hash(TicketRequest b) =>
        Canon.Etag(b.Id!.Value, b.Subject!, b.Priority!.Value, b.Escalated!.Value, b.Category!);

    Task<Ticket?> FindAny(Guid id, CancellationToken ct) =>
        _db.Tickets.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(t => t.PublicId == id, ct);

    [HttpPost]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created, "application/json")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK, "application/json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, ProblemType)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, ProblemType)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, ProblemType)]
    public async Task<IActionResult> Create([FromBody, Required] TicketRequest body, CancellationToken ct)
    {
        if (BodyInvalid(body) || body.Id == null || body.Id == Guid.Empty)
            return Err(400, "Invalid request body");

        var etag = Hash(body);
        var entity = new Ticket
        {
            PublicId = body.Id.Value,
            Subject = body.Subject!.Normalize(NormalizationForm.C),
            Priority = body.Priority!.Value,
            Escalated = body.Escalated!.Value,
            Category = body.Category!.Normalize(NormalizationForm.C),
            ETag = etag,
            CreateHash = etag
        };
        _db.Tickets.Add(entity);
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteErrorCode: 19 })
        {
            _db.ChangeTracker.Clear();
            var existing = await FindAny(body.Id.Value, ct);
            if (existing == null) return Err(409, "Conflict");
            if (existing.DeletedAt != null) return Err(410, "Gone");
            if (existing.CreateHash == etag || existing.ETag == etag)
            {
                Response.Headers.ETag = existing.ETag;
                return Ok(Map(existing));
            }
            return Err(409, "A ticket with this id and different content exists");
        }

        Response.Headers.ETag = etag;
        Response.Headers.Location = $"/api/support-tickets/{entity.PublicId:D}";
        return StatusCode(201, Map(entity));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK, "application/json")]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, ProblemType)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, ProblemType)]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var t = await FindAny(id, ct);
        if (t == null) return Err(404, "Not found");
        if (t.DeletedAt != null) return Err(410, "Gone");

        var now = DateTime.UtcNow;
        await _db.Tickets.Where(x => x.Id == t.Id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(x => x.ViewCount, x => x.ViewCount + 1)
                .SetProperty(x => x.LastViewedAt, now), ct);

        Response.Headers.ETag = t.ETag;
        if (Canon.Matches(Request.Headers.IfNoneMatch.ToString(), t.ETag))
            return StatusCode(304);
        return Ok(Map(t));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, ProblemType)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, ProblemType)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, ProblemType)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, ProblemType)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, ProblemType)]
    public async Task<IActionResult> Put(
        Guid id,
        [FromHeader(Name = "If-Match"), Required] string ifMatch,
        [FromBody, Required] TicketRequest body,
        CancellationToken ct)
    {
        if (BodyInvalid(body) || body.Id != id) return Err(400, "Invalid request body");
        var header = Request.Headers.IfMatch.ToString();
        if (string.IsNullOrWhiteSpace(header)) return Err(428, "If-Match header is required");

        var newEtag = Hash(body);
        var t = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t == null) return Err(404, "Not found");
        if (t.DeletedAt != null) return Err(410, "Gone");

        if (t.ETag == newEtag)
        {
            Response.Headers.ETag = t.ETag;
            return NoContent();
        }
        if (!Canon.Matches(header, t.ETag))
        {
            Response.Headers.ETag = t.ETag;
            return Err(412, "Precondition failed");
        }

        t.Subject = body.Subject!.Normalize(NormalizationForm.C);
        t.Priority = body.Priority!.Value;
        t.Escalated = body.Escalated!.Value;
        t.Category = body.Category!.Normalize(NormalizationForm.C);
        t.ETag = newEtag;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.ChangeTracker.Clear();
            var cur = await FindAny(id, ct);
            if (cur == null) return Err(404, "Not found");
            if (cur.DeletedAt != null) return Err(410, "Gone");
            Response.Headers.ETag = cur.ETag;
            if (cur.ETag == newEtag) return NoContent();
            return Err(412, "Precondition failed");
        }

        Response.Headers.ETag = newEtag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, ProblemType)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, ProblemType)]
    public async Task<IActionResult> Delete(
        Guid id,
        [FromHeader(Name = "If-Match"), Required] string ifMatch,
        CancellationToken ct)
    {
        var header = Request.Headers.IfMatch.ToString();
        if (string.IsNullOrWhiteSpace(header)) return Err(428, "If-Match header is required");

        var t = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t == null || t.DeletedAt != null) return NoContent();

        if (!Canon.Matches(header, t.ETag))
        {
            Response.Headers.ETag = t.ETag;
            return Err(412, "Precondition failed");
        }

        t.DeletedAt = DateTime.UtcNow;
        try
        {
            await _db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            _db.ChangeTracker.Clear();
            var cur = await FindAny(id, ct);
            if (cur == null || cur.DeletedAt != null) return NoContent();
            Response.Headers.ETag = cur.ETag;
            return Err(412, "Precondition failed");
        }
        return NoContent();
    }
}
