public abstract class ApiBase : ControllerBase
{
    protected readonly AppDb Db;
    protected ApiBase(AppDb db) { Db = db; }

    protected static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);

    protected void SetETag(Guid version) => Response.Headers.ETag = $"\"{version}\"";

    protected (bool Present, Guid? Value) IfMatch()
    {
        var h = Request.Headers.IfMatch.ToString().Trim();
        if (string.IsNullOrEmpty(h) || h == "*") return (false, null);
        if (h.StartsWith("W/")) h = h[2..];
        h = h.Trim('"');
        return (true, Guid.TryParse(h, out var g) ? g : Guid.Empty);
    }

    protected string? IdemKey() => Request.Headers["Idempotency-Key"].FirstOrDefault() is { Length: > 0 } k ? k : null;

    protected async Task<IActionResult?> Replay(string scope, string? key)
    {
        if (key == null) return null;
        var rec = await Db.IdempotencyRecords.AsNoTracking()
            .FirstOrDefaultAsync(r => r.Scope == scope && r.Key == key);
        if (rec == null) return null;
        Response.Headers.Location = rec.Location;
        return new ContentResult { StatusCode = 201, Content = rec.Body, ContentType = "application/json" };
    }

    protected IActionResult Created(string scope, string? key, string location, object dto, out IdempotencyRecord? rec)
    {
        var body = JsonSerializer.Serialize(dto, Json);
        rec = key == null ? null : new IdempotencyRecord { Scope = scope, Key = key, Body = body, Location = location };
        Response.Headers.Location = location;
        return new ContentResult { StatusCode = 201, Content = body, ContentType = "application/json" };
    }
}

