        if (err != null) return BadRequest(new { error = err });
        const string scope = "POST /api/warehouses";
        var key = IdemKey();
        if (await Replay(scope, key) is { } replay) return replay;

        var d = new Depot
        {
            Id = Guid.NewGuid(), Code = req!.Code!, CapacityCubicMeters = req.CapacityCubicMeters!.Value,
            LastAuditAt = DateTime.UtcNow, Version = Guid.NewGuid()
        };
        var result = Created(scope, key, $"/api/warehouses/{d.Id}", ToDto(d), out var rec);
        Db.Depots.Add(d);
        if (rec != null) Db.IdempotencyRecords.Add(rec);
        try { await Db.SaveChangesAsync(); }
        catch (DbUpdateException)
        {
            Db.ChangeTracker.Clear();
            Response.Headers.Remove("Location");
            if (await Replay(scope, key) is { } r2) return r2;
            throw;
