    {
        var err = Validate(req);
        if (err != null) return BadRequest(new { error = err });
        var (present, expected) = IfMatch();

        for (var attempt = 0; attempt < 8; attempt++)
        {
            var d = await Db.Depots.FirstOrDefaultAsync(x => x.Id == id);
            if (d == null) return NotFound();
            if (present && d.Version != expected) return StatusCode(412);
            d.Code = req!.Code!;
            d.CapacityCubicMeters = req.CapacityCubicMeters!.Value;
            d.LastAuditAt = DateTime.UtcNow;
            d.Version = Guid.NewGuid();
            try
            {
                await Db.SaveChangesAsync();
                SetETag(d.Version);
                return Ok(ToDto(d));
            }
            catch (DbUpdateConcurrencyException)
            {
                Db.ChangeTracker.Clear();
                if (present) return await Db.Depots.AnyAsync(x => x.Id == id) ? StatusCode(412) : NotFound();
            }
        }
        return Conflict();
