public static class Canon
{
    public static string Str(string s)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in s)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\b': sb.Append("\\b"); break;
                case '\f': sb.Append("\\f"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                default:
                    if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                    else sb.Append(c);
                    break;
            }
        }
        return sb.Append('"').ToString();
    }

    public static string Num(decimal d) =>
        d == 0 ? "0" : d.ToString("0.############################", CultureInfo.InvariantCulture);

    public static string Hash(string json) =>
        System.Buffers.Text.Base64Url.EncodeToString(SHA256.HashData(Encoding.UTF8.GetBytes(json)));

    public static string Depot(Guid id, string code, int cap) =>
        "{\"id\":\"" + id.ToString("D") + "\",\"code\":" + Str(code) +
        ",\"capacityCubicMeters\":" + cap.ToString(CultureInfo.InvariantCulture) + "}";

    public static string Consignment(Guid id, Guid wid, string reference, decimal w, bool fragile) =>
        "{\"id\":\"" + id.ToString("D") + "\",\"warehouseId\":\"" + wid.ToString("D") + "\",\"reference\":" +
        Str(reference) + ",\"weightKg\":" + Num(w) + ",\"fragile\":" + (fragile ? "true" : "false") + "}";
}

