[AttributeUsage(AttributeTargets.Method, AllowMultiple = true)]
public class ProblemResponseAttribute(int status)
    : ProducesResponseTypeAttribute(typeof(ProblemDetails), status, "application/problem+json");

public abstract class ApiBase : ControllerBase
{
    protected IActionResult Fail(int code, string title, string? etag = null)
    {
        if (etag != null) SetETag(etag);
        return new ObjectResult(new ProblemDetails { Status = code, Title = title })
        {
            StatusCode = code,
            ContentTypes = { "application/problem+json" }
        };
    }

    protected void SetETag(string etag) => Response.Headers.ETag = "\"" + etag + "\"";

    protected static bool TagMatches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var p in header.Split(','))
        {
            var t = p.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/")) t = t[2..];
            if (t.Trim('"') == etag) return true;
        }
        return false;
    }

    protected static bool IsUnique(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteErrorCode: 19 } s &&
        s.Message.Contains("UNIQUE", StringComparison.OrdinalIgnoreCase);

    protected static async Task SaveAsync(DbContext db, CancellationToken ct)
    {
        for (var attempt = 0; ; attempt++)
        {
            try { await db.SaveChangesAsync(ct); return; }
            catch (DbUpdateException ex) when (attempt < 8 && ex is not DbUpdateConcurrencyException &&
                                               ex.InnerException is SqliteException { SqliteErrorCode: 5 or 6 })
            {
                await Task.Delay(25 * (attempt + 1), ct);
            }
        }
    }
}

